<script setup lang="ts">
import { ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { DataBoard, Calendar, DocumentChecked, User, Monitor, Setting, Timer, List, ArrowRight, Menu, SwitchButton, Lock, Camera } from '@element-plus/icons-vue'
import { useAuth } from '../stores/auth'
import { ElMessage } from 'element-plus'
import { errorText } from '../api'
const auth = useAuth(), route = useRoute(), router = useRouter(), open = ref(false)
const nav = [{ path:'/', title:'考勤概览', icon:DataBoard },{ path:'/attendance', title:'考勤记录',icon:Calendar },{ path:'/requests',title:'请假与补卡',icon:DocumentChecked }]
const adminNav = [{path:'/employees',title:'人员与部门',icon:User},{path:'/devices',title:'打卡设备',icon:Monitor},{path:'/rules',title:'规则与日历',icon:Timer},{path:'/settings',title:'系统运行',icon:Setting},{path:'/audit',title:'操作日志',icon:List}]
async function logout() { try { await auth.logout(); await router.push('/login') } catch (e) { ElMessage.error(errorText(e)) } }
</script>
